-- Original competency practice for Saudi G10, both semesters.
-- The existing competency headings are broad; this does NOT certify an official
-- lesson-by-lesson textbook or title match. Preserves IDs and learner progress.
DO $dadyoom$
DECLARE r record; target_id uuid; previous_text text; changed integer; used_count integer;
BEGIN
 FOR r IN SELECT * FROM jsonb_to_recordset('[{"sem":1,"n":1,"title":"الكفاية النحوية — الكفايات اللغوية 1","skill":"تمييز الجملة الاسمية ومكوناتها","passage":"تتألف الجملة الاسمية في أبسط صورها من مبتدأ وخبر مثل «الكتابُ مفيدٌ»، فكلمة «الكتابُ» مبتدأ مرفوع و«مفيدٌ» خبر مرفوع. ننتبه إلى أن تقديم ظرف أو جار ومجرور قد يغير ترتيب التحليل، فلا نحكم من ترتيب الكلمات فقط. مثال ضاديوم مستقل يوازن بين «المكتبةُ واسعةٌ» و«في المكتبةِ كتبٌ» لبيان التقديم دون أن يمثل ترتيب الكتاب الوزاري.","q1":"ما الخبر في «الكتابُ مفيدٌ»؟","a1":"مفيدٌ","w1":["الكتابُ","في","من"],"q2":"ما إعراب «الكتابُ»؟","a2":"مبتدأ مرفوع","w2":["مفعول به","فاعل لفعل محذوف بالضرورة","اسم مجرور"],"writing":"أعرب جملتين اسميتين من إنشائك مع تمييز المبتدأ والخبر وعلامة إعرابهما."},{"sem":1,"n":2,"title":"الكفاية الإملائية — الكفايات اللغوية 1","skill":"رسم الهمزة المتوسطة بحسب الحركات","passage":"في كلمة «سَأَلَ» كُتبت الهمزة المتوسطة على الألف لمناسبة الفتحة في موضعها وفق ترتيب قوة الحركات، بينما في «سُئِلَ» كُتبت على نبرة لمناسبة الكسرة الأقوى. تقتضي الكتابة الدقيقة النظر إلى حركة الهمزة وما قبلها وإجراء القاعدة على الكلمة الحقيقية، لا التخمين من هيئة الكلمة. المثالان تدريبيان أصليان غير منسوبين إلى درس وزاري محدد.","q1":"كيف كتبت الهمزة في «سُئِل»؟","a1":"على نبرة","w1":["على واو","على السطر","على ألف"],"q2":"أي حركة هي الأقوى في رسم الهمزة المتوسطة؟","a2":"الكسرة","w2":["الفتحة","السكون","الضمة"],"writing":"اكتب ست كلمات متنوعة الهمزة المتوسطة وبين الحركتين المؤثرتين وسبب اختيار الرسم."},{"sem":1,"n":3,"title":"الكفاية القرائية — الكفايات اللغوية 1","skill":"الفكرة الرئيسة والدليل النصي","passage":"لفهم فقرة نحدد الموضوع وما يقوله الكاتب عنه، ثم نميز الفكرة الرئيسة من تفصيل يدعمها. في نص أصلي «فتحت المدرسة المكتبة قبل الحصص؛ ليجد الطلاب وقتًا مناسبًا للقراءة. وازدادت طلبات استعارة الكتب في الأسبوع الأول». الفكرة هي تيسير القراءة، والزيادة دليل على الإقبال ضمن هذه القصة، لا إحصاء حقيقي. نتجنب تحويل تفصيل واحد إلى حكم عام دون دليل.","q1":"ما الفكرة الرئيسة في المثال؟","a1":"تسهيل القراءة بإتاحة المكتبة مبكرًا","w1":["عدد أبواب المدرسة","وصف الطقس","تاريخ إنشاء المكتبة"],"q2":"ما التفصيل الداعم للإقبال على القراءة في النص؟","a2":"زيادة طلبات استعارة الكتب","w2":["اسم المدرسة","لون الجدران","عدد النوافذ"],"writing":"استخرج الفكرة الرئيسة ودليلين من نص قصير موثق أو من كتابتك مع تمييز الفكرة عن التفصيل."},{"sem":1,"n":4,"title":"كفاية الاتصال الكتابي — الكفايات اللغوية 1","skill":"بناء فقرة ذات فكرة وتفسير وخاتمة","passage":"تبدأ الفقرة الواضحة بجملة موضوعية، تتبعها تفاصيل أو دليل، ثم جملة تربط النتيجة بالفكرة. في تدريب مستقل: «تساعد المراجعة قبل التسليم على رفع جودة الأعمال. فقد اكتشف فريق خطأ في الجدول أثناء المراجعة، وعدله قبل الموعد؛ لذلك جعل الفريق المراجعة خطوة أساسية». يمكن تعزيز الفقرة ببيان معايير التحقق بدل تكرار الفكرة.","q1":"أي جملة تعرض نتيجة المراجعة في المثال؟","a1":"جعل الفريق المراجعة خطوة أساسية","w1":["تساعد المراجعة","فقد اكتشف فريق خطأ","قبل الموعد"],"q2":"ما وظيفة المثال داخل الفقرة؟","a2":"توضيح الفكرة الرئيسة بدليل","w2":["تغيير الموضوع","حذف الخاتمة","زيادة الكلمات بلا معنى"],"writing":"اكتب فقرة من خمس جمل تتضمن فكرة واحدة وشاهدًا وتفسيرًا وخاتمة مترابطة."},{"sem":1,"n":5,"title":"كفاية التواصل الشفهي — الكفايات اللغوية 1","skill":"عرض شفهي منظم بالوقت والأدلة","passage":"يتطلب التقديم الشفهي تحديد هدف الجمهور، ومقدمة موجزة تذكر الموضوع، ونقطتين مرتبتين، وخاتمة تراجع الفكرة. في مثال مستقل يقدم طالب دقيقتين عن ترشيد الماء: يسأل سؤالًا افتتاحيًا ويشرح ممارسة منزلية ثم يدعو إلى قياس الاستهلاك. لا يُعد ارتفاع الصوت وحده دليلًا على قوة الخطاب؛ فالوضوح والإنصات للسؤال ضروريان.","q1":"ما الخطوة المناسبة بعد افتتاح العرض؟","a1":"عرض نقاط مرتبة مع أمثلة","w1":["ترك الموضوع بلا ترتيب","قراءة العنوان فقط","تجاهل الجمهور"],"q2":"ما معيار التقديم الجيد في المثال؟","a2":"وضوح الفكرة واحترام الوقت والجمهور","w2":["رفع الصوت دائمًا","سرعة الكلام وحدها","تكرار الجملة بلا هدف"],"writing":"سجل عرضًا مدته دقيقة مع افتتاح ونقطتين وخاتمة، ثم قيم سرعة الكلام والوضوح بمساعدة زميل."},{"sem":2,"n":1,"title":"الكفاية النحوية — الكفايات اللغوية 1","skill":"الفعل والفاعل والمفعول به في الجملة","passage":"في «كتبَ الطالبُ الملخصَ» «كتبَ» فعل ماض و«الطالبُ» فاعل مرفوع و«الملخصَ» مفعول به منصوب، أما «جلسَ الطالبُ» فيكتفي بالفاعل في هذا الاستعمال. نميّز الفعل المتعدي من اللازم داخل جملته، ونبحث عن علامة الإعراب قبل تسمية وظيفة الكلمة. المثال مستقل وغير منسوب إلى صفحات الفصل الثاني.","q1":"ما إعراب «الملخصَ» في المثال؟","a1":"مفعول به منصوب","w1":["فاعل مرفوع","مبتدأ مرفوع","مضاف إليه"],"q2":"أي الجملتين فعلها متعد في المثال؟","a2":"كتب الطالب الملخص","w2":["جلس الطالب","نام الطفل","سافر المسافر"],"writing":"حلل ثلاث جمل فعلية مع بيان نوع الفعل وموقع الفاعل والمفعول إن وجد."},{"sem":2,"n":2,"title":"الكفاية الإملائية — الكفايات اللغوية 1","skill":"التمييز بين التاء المربوطة والمفتوحة والهاء","passage":"في «مدرسة» تاء مربوطة تُنطق هاء عند الوقف في الفصحى، وفي «بيت» تاء أصلية مفتوحة، أما في «وجه» فالهاء حرف أصلي. يساعد جمع الكلمة وتصريفها على التمييز حين يلتبس الرسم، ولا تُستبدل كل هاء في نهاية الكلمة بتاء مربوطة. النص تدريبي أصلي وليس صفحة من الكتاب.","q1":"ما الحرف الأخير في «مدرسة»؟","a1":"تاء مربوطة","w1":["تاء مفتوحة","هاء أصلية","ألف مقصورة"],"q2":"أي كلمة تنتهي بتاء مفتوحة؟","a2":"بيت","w2":["مدرسة","شجرة","وجه"],"writing":"اكتب ثماني كلمات بنهايات مختلفة وصنفها، ثم علل رسم أربع كلمات منها."},{"sem":2,"n":3,"title":"الكفاية القرائية — الكفايات اللغوية 1","skill":"الاستدلال على المعنى الضمني والتمييز بين الرأي والحقيقة","passage":"يستنتج القارئ معنى غير مصرح به عندما يجمع قرائن من النص دون أن يضيف تفاصيل لا دليل عليها. مثال مستقل: «وصلت ريم إلى القاعة قبل الموعد بعشر دقائق، وراجعت بطاقة العرض ثم جهزت أوراقها». يمكن استنتاج استعدادها للعرض، لكن لا يمكن معرفة درجتها النهائية. ونميز بين عبارة قابلة للتحقق مثل الموعد وبين حكم ذاتي على جودة العرض.","q1":"ما الاستنتاج المسنود في المثال؟","a1":"أن ريم تستعد لعرض منظم","w1":["أنها حصلت على الدرجة الكاملة","أنها قدمت في مدينة أخرى","أنها نسيت الأوراق"],"q2":"ما المعلومة الصريحة في المثال؟","a2":"وصلت قبل الموعد بعشر دقائق","w2":["نجحت بتفوق","كان الجمهور كبيرًا","استغرق العرض ساعة"],"writing":"اكتب فقرة فيها معلومتان صريحتان واستنتاج محتمل، ثم حدد قرينة كل استنتاج وحدوده."},{"sem":2,"n":4,"title":"كفاية الاتصال الكتابي — الكفايات اللغوية 1","skill":"رسالة رسمية واضحة تحترم المخاطب","passage":"تتطلب الرسالة الرسمية تحديد الجهة والموضوع وطلبًا واضحًا وسببًا مختصرًا وخاتمة مهذبة. في نموذج من ضاديوم يطلب طالب من إدارة المكتبة تمديد الاستعارة يومين بسبب مشروع دراسي، ويذكر تاريخ إعادة الكتاب المقترح. لا يستخدم لغة اتهامية أو مبالغة، ويحتفظ بالمعلومات الضرورية دون بيانات شخصية حساسة.","q1":"ما العنصر الأهم لوضوح الرسالة الرسمية؟","a1":"طلب محدد ومسبب","w1":["حذف الموضوع","الإسهاب في المدح","المبالغة في علامات التعجب"],"q2":"ما الذي يجب أن يتضمنه طلب التمديد؟","a2":"مدة التمديد والسبب والموعد المقترح","w2":["رأي زملاء لا صلة لهم","تفاصيل شخصية غير لازمة","إشاعة عن الإدارة"],"writing":"صغ رسالة مهنية قصيرة تطلب خدمة مدرسية، ثم راجع لغتها وتنظيمها ووضوح المطلوب."},{"sem":2,"n":5,"title":"كفاية التواصل الشفهي — الكفايات اللغوية 1","skill":"المناقشة واحترام الدور والحجة","passage":"تحتاج المناقشة الجيدة إلى الإصغاء وتلخيص رأي الطرف الآخر قبل الرد، وإسناد الاعتراض إلى سبب، والتمييز بين نقد الفكرة ونقد الشخص. في محاكاة مستقلة يناقش طالبان تخصيص وقت للأنشطة؛ يقدم الأول مزية ويذكر الثاني قيدًا في الجدول، ثم يتفقان على تجربة قصيرة قابلة للتقييم.","q1":"ما السلوك الأنسب قبل الاعتراض؟","a1":"الاستماع وتلخيص الفكرة بدقة","w1":["مقاطعة المتحدث","السخرية من الشخص","تجاهل الدليل"],"q2":"ما الطريقة العملية لحسم الخلاف في المثال؟","a2":"تجربة محدودة ومعايير مراجعة واضحة","w2":["رفع الصوت","الرفض دون سبب","تبديل موضوع النقاش"],"writing":"أدر نقاشًا في ثلاثة أدوار وحدد حجة واعتراضًا وردًا يحترم الطرفين."}]'::jsonb) AS x(
   sem integer,n integer,title text,skill text,passage text,q1 text,a1 text,w1 text[],
   q2 text,a2 text,w2 text[],writing text
 ) LOOP
   SELECT l.id,l.content INTO STRICT target_id,previous_text
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id
    JOIN public.curricula cu ON cu.id=g.curriculum_id
    JOIN public.countries co ON co.id=cu.country_id
    WHERE co.code='SA' AND cu.id='f42518c1-c7bd-45da-bb37-69cf9eca0a56'::uuid
     AND g.grade_number=10 AND u.semester=r.sem
     AND l.sort_order=r.n AND l.title=r.title AND l.status='published'
    FOR UPDATE OF l;
   SELECT count(*) INTO used_count FROM public.student_lesson_progress
     WHERE lesson_id=target_id;
   IF used_count<>0 THEN RAISE EXCEPTION 'SA_G10_EXISTING_PROGRESS_%',r.title; END IF;
   SELECT count(*) INTO used_count FROM public.lesson_activity_attempts att
     JOIN public.lesson_activities a ON a.id=att.activity_id WHERE a.lesson_id=target_id;
   IF used_count<>0 THEN RAISE EXCEPTION 'SA_G10_EXISTING_ATTEMPT_%',r.title; END IF;
   IF char_length(coalesce(previous_text,''))>=350 THEN
     RAISE EXCEPTION 'SA_G10_ALREADY_FULL_%',r.title;
   END IF;
   SELECT count(*) INTO changed FROM public.lesson_activities
      WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
   IF changed<>3 THEN RAISE EXCEPTION 'SA_G10_ACTIVITY_MISMATCH_%_%',r.title,changed; END IF;
   UPDATE public.lessons SET
      content='ضاديوم — إثراء لغوي أصلي للصف الأول الثانوي بالسعودية، الفصل '||r.sem::text
        ||'. هذه وحدة مهارية عامة، ولم تُتحقق مطابقتها التفصيلية بفهرس صفحات الكتاب الوزاري.'
        ||E'\n\n'||'المهارة: '||r.skill
        ||E'\n\n'||'الشرح والتطبيق: '||r.passage
        ||E'\n\n'||'هدف قابل للقياس: أن يفسر المتعلم القاعدة أو الفكرة في المثال، ويستدل على صحة استجابته، ثم ينقل المهارة إلى موقف جديد.'
        ||E'\n\n'||'سؤال تطبيقي أول: '||r.q1
        ||E'\n\n'||'سؤال تطبيقي ثان: '||r.q2
        ||E'\n\n'||'مهمة إنتاج: '||r.writing
        ||E'\n\n'||'التمايز: للمبتدئ نموذج محلول وأسئلة إرشادية؛ وللمتوسط تدريب مستقل مع مراجعة؛ وللمتقدم تعليل قاعدة أو نقد بديل. يراجع المعلم الإجابة الكتابية، ولا تُنسب هذه الأمثلة إلى الكتاب الرسمي.'
        ||E'\n\n'||'المدخل السابق محفوظ: '||coalesce(previous_text,''),
        updated_at=now() WHERE id=target_id;

   UPDATE public.lesson_activities SET prompt=r.q1,
      content=content||jsonb_build_object('origin','DADYOOM_SA_G10_TERM12_ORIGINAL_V1_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
        'text',r.q1,'notOfficialBook',true,'sourceVerification','pending',
        'options',CASE ((r.n+r.sem)%4)
          WHEN 0 THEN jsonb_build_array(r.a1,r.w1[1],r.w1[2],r.w1[3])
          WHEN 1 THEN jsonb_build_array(r.w1[1],r.a1,r.w1[2],r.w1[3])
          WHEN 2 THEN jsonb_build_array(r.w1[1],r.w1[2],r.a1,r.w1[3])
          ELSE jsonb_build_array(r.w1[1],r.w1[2],r.w1[3],r.a1) END),
      answer=jsonb_build_object('correct',r.a1)
    WHERE lesson_id=target_id AND activity_order=1 AND activity_type='multiple_choice'
       AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
   UPDATE public.lesson_activities SET prompt=r.q2,
      content=content||jsonb_build_object('origin','DADYOOM_SA_G10_TERM12_ORIGINAL_V1_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
        'text',r.q2,'notOfficialBook',true,'sourceVerification','pending',
        'options',CASE ((r.n+r.sem+1)%4)
          WHEN 0 THEN jsonb_build_array(r.a2,r.w2[1],r.w2[2],r.w2[3])
          WHEN 1 THEN jsonb_build_array(r.w2[1],r.a2,r.w2[2],r.w2[3])
          WHEN 2 THEN jsonb_build_array(r.w2[1],r.w2[2],r.a2,r.w2[3])
          ELSE jsonb_build_array(r.w2[1],r.w2[2],r.w2[3],r.a2) END),
      answer=jsonb_build_object('correct',r.a2)
    WHERE lesson_id=target_id AND activity_order=2 AND activity_type='multiple_choice'
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
   UPDATE public.lesson_activities SET prompt=r.writing,
     content=content||jsonb_build_object('origin','DADYOOM_SA_G10_TERM12_ORIGINAL_V1_20261009','previousOrigin','DADYOOM_SA_OFFICIAL_2026_2027_V1',
      'text',r.writing,'notOfficialBook',true,'humanReviewRequired',true,
      'sourceVerification','pending')
     WHERE lesson_id=target_id AND activity_order=3 AND activity_type='writing'
      AND content->>'origin'='DADYOOM_SA_OFFICIAL_2026_2027_V1';
   SELECT count(*) INTO changed FROM public.lesson_activities
     WHERE lesson_id=target_id AND content->>'origin'='DADYOOM_SA_G10_TERM12_ORIGINAL_V1_20261009';
   IF changed<>3 THEN RAISE EXCEPTION 'SA_G10_UPDATE_FAILED_%',r.title; END IF;
 END LOOP;
END $dadyoom$;